import type { LunariaUserConfig } from '@lunariajs/core'
import { defaultLocale, locales, translatedLocales } from './src/lib/locales.mjs'

export default {
	repository: { name: 'elysiajs/documentation', branch: 'next' },
	sourceLocale: {
		label: locales[defaultLocale].label,
		lang: locales[defaultLocale].lang
	},
	locales: translatedLocales.map((lang) => ({
		label: locales[lang].label,
		lang
	})) as LunariaUserConfig['locales'],
	files: [
		{
			include: [`src/content/docs/${defaultLocale}/**/*.{md,mdx}`],
			exclude: [
				// generated by starlight-typedoc
				`src/content/docs/${defaultLocale}/reference/**`,
				`src/content/docs/${defaultLocale}/design-system.mdx`
			],
			pattern: {
				source: `src/content/docs/${defaultLocale}/@path`,
				locales: 'src/content/docs/@lang/@path'
			},
			type: 'universal'
		}
	]
} satisfies LunariaUserConfig
